import { z } from 'zod';
import type { Instant } from '../primitives';
import { uuidSchema, type UUID } from './common';

/** Largest single movement or target quantity accepted from the UI. */
export const MAX_STOCK_QUANTITY = 1_000_000_000;

const quantity = (min: number) =>
  z
    .number('validation.invalid')
    .int('validation.invalid')
    .min(min, 'validation.invalid')
    .max(MAX_STOCK_QUANTITY, 'validation.invalid');

/** Generated by the renderer once per user submission; reused on a retry. */
const requestId = uuidSchema;

export const stockItemInputSchema = z.strictObject({
  catalogItemId: uuidSchema,
});
export type StockItemInput = z.infer<typeof stockItemInputSchema>;

export const listStockInputSchema = z.strictObject({
  query: z
    .string('validation.invalid')
    .trim()
    .max(100, 'validation.tooLong')
    .optional(),
  /** Only items whose stock is below zero (spec 25). */
  negativeOnly: z.boolean('validation.invalid').optional(),
  limit: z.number('validation.invalid').int().min(1).max(200).optional(),
});
export type ListStockInput = z.input<typeof listStockInputSchema>;

export const stockHistoryInputSchema = z.strictObject({
  catalogItemId: uuidSchema,
  limit: z.number('validation.invalid').int().min(1).max(500).optional(),
});
export type StockHistoryInput = z.input<typeof stockHistoryInputSchema>;

export const openBalanceInputSchema = z.strictObject({
  requestId,
  catalogItemId: uuidSchema,
  quantity: quantity(0),
});
export type OpenBalanceInput = z.input<typeof openBalanceInputSchema>;

export const receiveStockInputSchema = z.strictObject({
  requestId,
  catalogItemId: uuidSchema,
  quantity: quantity(1),
  note: z
    .string('validation.invalid')
    .trim()
    .max(500, 'validation.tooLong')
    .optional(),
});
export type ReceiveStockInput = z.input<typeof receiveStockInputSchema>;

/**
 * `reason` may be missing or blank at the schema level on purpose: the
 * service answers REASON_REQUIRED (a specific, translated message).
 */
const reason = z
  .string('validation.invalid')
  .trim()
  .max(500, 'validation.tooLong')
  .optional();

export const adjustStockInputSchema = z.strictObject({
  requestId,
  catalogItemId: uuidSchema,
  quantityDelta: z
    .number('validation.invalid')
    .int('validation.invalid')
    .min(-MAX_STOCK_QUANTITY, 'validation.invalid')
    .max(MAX_STOCK_QUANTITY, 'validation.invalid')
    .refine((value) => value !== 0, 'validation.invalid'),
  reason,
});
export type AdjustStockInput = z.input<typeof adjustStockInputSchema>;

export const setStockInputSchema = z.strictObject({
  requestId,
  catalogItemId: uuidSchema,
  /** May be negative: the ledger allows it (spec 25). */
  targetQuantity: z
    .number('validation.invalid')
    .int('validation.invalid')
    .min(-MAX_STOCK_QUANTITY, 'validation.invalid')
    .max(MAX_STOCK_QUANTITY, 'validation.invalid'),
  reason,
});
export type SetStockInput = z.input<typeof setStockInputSchema>;

export type MovementType =
  | 'OPENING_BALANCE'
  | 'STOCK_IN'
  | 'SALE'
  | 'VOID_REVERSAL'
  | 'ADJUSTMENT';

export interface StockDto {
  catalogItemId: UUID;
  /** SUM(quantity_delta); may be negative. */
  quantity: number;
}

export interface StockListItemDto {
  catalogItemId: UUID;
  title: string;
  sku: string | null;
  unitLabel: string;
  isActive: boolean;
  quantity: number;
  isNegative: boolean;
}

export interface StockListDto {
  items: StockListItemDto[];
}

/** Result of every stock write. `entryId` is null when nothing was written. */
export interface StockChangeDto {
  entryId: UUID | null;
  catalogItemId: UUID;
  quantityDelta: number;
  newQuantity: number;
}

export interface LedgerEntryDto {
  id: UUID;
  movementType: MovementType;
  quantityDelta: number;
  referenceType: string | null;
  referenceId: string | null;
  note: string | null;
  reversesEntryId: UUID | null;
  createdByCashierId: UUID;
  cashierName: string;
  createdAt: Instant;
}

export interface LedgerDto {
  catalogItemId: UUID;
  /** Shop timezone for displaying `createdAt`. */
  timezone: string;
  /** Newest first. */
  entries: LedgerEntryDto[];
}
